import type { Catalog } from './connection.ts';

export function assertSourceName(name: string) {
  if (!/^[a-z][a-z0-9_-]*$/i.test(name)) {
    throw new Error(`Invalid flags source name: ${JSON.stringify(name)}`);
  }
}

export function renderModule(source: string, catalog: Catalog): string {
  assertSourceName(source);

  const lines = [
    '// Generated by pnpm flags:sync. Do not edit.',
    "import 'server-only';",
    `import provider from '../flags/sources/${source}/provider.ts';`,
    `import getEvaluationContext from '../flags/sources/${source}/context.ts';`,
    "import { defineConnection } from 'flags';",
    "import { createFlag } from 'flags/next';",
    '',
    'const connection = defineConnection({ provider, getEvaluationContext });',
    '',
  ];

  for (const [index, [key, flag]] of Object.entries(catalog.flags)
    .sort(([left], [right]) => left.localeCompare(right, 'en'))
    .entries()) {
    // Use private identifiers, so keys can include punctuation or reserved words.
    const local = `flag_${index}`;
    if (flag.description) {
      lines.push(
        '/**',
        ...flag.description
          .replace(/\*\//g, '*\\/')
          .split(/\r?\n/)
          .map((line) => ` * ${line}`),
        ' */',
      );
    }
    lines.push(
      `const ${local} = createFlag(connection, ${JSON.stringify(key)}, ${JSON.stringify(flag.variants)} as const, ${JSON.stringify(catalog.id)});`,
      `export { ${local} as ${JSON.stringify(key)} };`,
      '',
    );
  }

  return lines.join('\n');
}
